Task 1a: State Electricity Profiles


Show Data Acquisition Code
get_eia_sep &lt;- function(state, abbr){
    library(tidyverse)
    library(stringr)
    library(httr2)
    library(rvest)
    library(fs)

    state_formatted &lt;- str_to_lower(state) |&gt; str_replace_all("\\s", "")

    dir_name &lt;- fs::path("data", "mp02")
    file_name &lt;- fs::path(dir_name, state_formatted)

    fs::dir_create(dir_name, recurse=TRUE)

    if(!fs::file_exists(file_name)){
        BASE_URL &lt;- "https://www.eia.gov"
        RESPONSE &lt;- request(BASE_URL) |&gt; 
          req_url_path("electricity", 
                       "state", 
                       state_formatted) |&gt;
          req_headers(
            `User-Agent` = "Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:149.0) Gecko/20100101 Firefox/149.0"
            ) |&gt;   
          req_retry(
                max_tries = 4, 
          ) |&gt;
          req_perform(file_name)

        resp_check_status(RESPONSE)
    }

    TABLE &lt;- read_html(file_name) |&gt; 
        html_element("table") |&gt; 
        html_table() |&gt;
        mutate(Item = str_to_lower(Item))

    if("U.S. rank" %in% colnames(TABLE)){
        TABLE &lt;- TABLE |&gt; rename(Rank = `U.S. rank`)
    }

    CO2_MWh &lt;- TABLE |&gt; 
        filter(Item == "carbon dioxide (lbs/mwh)") |&gt;
        pull(Value) |&gt; 
        str_replace_all(",", "") |&gt;
        as.numeric()

    PRIMARY &lt;- TABLE |&gt; 
        filter(Item == "primary energy source") |&gt; 
        pull(Rank)

    RATE &lt;- TABLE |&gt;
        filter(Item == "average retail price (cents/kwh)") |&gt;
        pull(Value) |&gt;
        as.numeric()

    GENERATION_MWh &lt;- TABLE |&gt;
        filter(Item == "net generation (megawatthours)") |&gt;
        pull(Value) |&gt;
        str_replace_all(",", "") |&gt;
        as.numeric()

    data.frame(CO2_MWh               = CO2_MWh, 
               primary_source        = PRIMARY,
               electricity_price_MWh = RATE * 10, # / 100 cents to dollars &
               # * 1000 kWh to MWH 
               generation_MWh        = GENERATION_MWh, 
               state                 = state, 
               abbreviation          = abbr
    )
}

EIA_SEP_REPORT &lt;- map2(state.name, state.abb, get_eia_sep) |&gt; list_rbind()


By doing these steps, we collected state-level electricity data from the U.S. Energy Information Administration (EIA) using the provided R function. The resulting dataset, EIA_SEP_REPORT, contains 50 observations and 6 variables, including CO₂ emissions per MWh, primary energy source, electricity price, and total electricity generation.
This dataset will help us estimate the environmental impact of electricity consumption by public transit systems across different states.






